INSERT INTO `tickets` VALUES (1,'IVS Site Ticket aanvraag','Ruben Struijlaart','rstruijlaart@student.scalda.nl','Bezig','-','Ruben Struijlaart','Korben de Vos','Er is op het moment geen manier voor bestaande klanten om \r\ntickets in te dienen zonder apart contact met ons op te nemen, ik wil dat hier een apart formulier voor komt op de site zodat wij netjes alle tickets binnen krijgen. en dat klanten een automatisch een reactie terug krijgen','IS-2021-001','Normaal'),(3,'ZAOS','Willem Poppe','poppe@zaos.nl','Afgerond','-','Aaron Wakefield','Yari Morcus','• Geboortedatum, studentennummer en mobiele telefoonnummer graag nog als extra velden die ik kan invullen bij de LIO\r\n\r\n• Spelfout in \'code bekostiging\'\r\n\r\n• LIO\'s moeten ook kunnen worden verwijderd, zeker nu in de testfase, dus graag veld \'Delete\' toevoegen.\r\n\r\n• Het lukt me nog niet om een nieuw aangemaakte LIO ook aan een opleidingslocatie te koppelen. Als ik op \'LIO beheren\' klik (bijv. Vivien Melis) en de door mij aangemaakte opleidingslocatie (CSW v/d Perre) selecteer en dit bevestig blijft dit niet staan. Ook het leerjaar blijft verspringen naar jaar 4, terwijl ik steeds jaar 3 selecteer.\r\n\r\n• Wat wordt er bedoeld met het begrip \'Status\'? Wat voor \'status\' zou ik daar kunnen invoeren?','ES-2021-003','Normaal'),(4,'ZAOS','Willem Poppe','poppe@zaos.nl','Afgerond','-','Willem Poppe','Jeffrey Scheffers','Op het actiescherm staat een aantal blokjes\r\n•	De blokjes zouden dezelfde grootte krijgen. \r\n•	Het woord beheren kan weg, want dat is overal aan de orde. \r\n•	LiO moet het eerste blokje zijn: dat is de belangrijkste. \r\n•	Stageplek beheren moet zijn : aantal plaatsen','ES-2021-004','Normaal'),(5,'IVS Site','Tristan Verschueren','rstruijlaart@student.scalda.nl','Ingediend','-','Ruben Struijlaart','Oktay','op de site bij het stukje \"\"Wij ontwikkelen web-gebaseerde applicaties, websites, mobiele applicaties en nog veel meer. Wij zorgen ervoor dat u geen hulp meer nodig hebt, \r\ndoor een handleiding mee te sturen, als het project wordt opgeleverd.\"\" moet \"\"Wij zorgen ervoor dat u geen hulp meer nodig hebt, door een handleiding mee te sturen, als het project wordt opgeleverd.\"\" vervangen worden door \"Deze zullen dan helemaal op uw wens gemaakt worden.\"','IS-2022-001','Normaal'),(6,'IVS Site','Ruben Struijlaart','rstruijlaart@student.scalda.nl','Ingediend','-','Ruben Struijlaart','Jeffrey Scheffers','Bij het meeloop formulier moet het veldje leeftijd weg.','IS-2022-002','Normaal'),(8,'IVS Site','Ruben Struijlaart','rstruijlaart@student.scalda.nl','Ingediend','-','Ruben Struijlaart','-','','IS-2022-004','Normaal'),(9,'VVEI Zeeland','Jeanneke Niewenhuijse','Jeanneke@itngroep.nl','Ingediend','-','Jeanneke Niewenhuijse','Miko','Het contactformulier op de website www.vveizeeland.nl werkt niet meer. Er komt een foutmelding bij het versturen van het formulier. ','ES-2022-05','Hoog'),(10,'VVEI Zeeland','Jeanneke Niewenhuijse','Jeanneke@itngroep.nl','Ingediend','-','Jeanneke Niewenhuijse','-','We zouden graag bij het klikken op de logo\'s op de pagina \'vrienden op de websites van deze vrienden uit willen komen.','ES-2022-06','Hoog'),(11,'VVEI Zeeland','Jeanneke Niewenhuijse','Jeanneke@itngroep.nl','Ingediend','-','Jeanneke Niewenhuijse','-','De homepagina bestaat nu uit 1 vaste foto. We zouden graag een slide willen van deze foto, zodat er meerdere foto\'s zichtbaar zijn. We zouden deze ook zelf willen wijzigen af en toe. Is dat mogelijk?','ES-2022-07','Hoog'),(12,'IVS Templates website','Tristan Verschueren','227967@student.scalda.nl','Afgerond','Gerhard','Sander Bruggeman','JoÃ«l Schout','Ik zie op de template website van IVS een bugje.\r\nIn de toggle voor de dark mode staat vreemde tekst\r\ndit zou een maantje en een zonnetje moeten worden\r\n','IS-2022-08','Normaal');
